-- Run only as a transaction: no test applicant or commercial changes persist.
begin;
do $$
declare a uuid; manager_id uuid=gen_random_uuid(); seller_id uuid=gen_random_uuid(); blocked_id uuid=gen_random_uuid(); protocol1 text; protocol2 text; rid uuid; raw jsonb; result jsonb; vid uuid; price numeric; customer uuid; n integer; institution uuid; taskid uuid;
 p jsonb=jsonb_build_object('applicant_name','Teste Transacional Ficha','cpf','52998224725','birth_date','1990-01-01','phone','5551999999999','email','financing-test@example.invalid','city','Teste','state','RS','employment_type','employed','employment_bond','clt','employment_duration','over_2','occupation','Teste','income_range','under_2000','additional_income',false,'has_trade_in',false,'down_payment',100,'desired_term',24,'notes','','extra_answers','{}'::jsonb);
 key uuid=gen_random_uuid();
begin
 select id into a from public.motta_profiles where active and role='admin' limit 1;
 if a is null then raise exception 'An active admin is required for this integration test';end if;
 insert into auth.users(id) values(manager_id),(seller_id),(blocked_id);
 insert into public.motta_profiles(id,full_name,role,active) values(manager_id,'Teste gerente transacional','manager',true),(seller_id,'Teste vendedor transacional','seller',true),(blocked_id,'Teste bloqueado transacional','admin',false);
 perform set_config('request.jwt.claim.sub',a::text,true);
 if has_table_privilege('anon','public.motta_financing_applications','select') or has_function_privilege('anon','public.motta_financing_receive(jsonb,uuid,text)','execute') or has_function_privilege('authenticated','public.motta_financing_receive(jsonb,uuid,text)','execute') then raise exception 'Public data/submission permissions exposed';end if;
 update public.motta_financing_settings set enabled=true,legal_validated=true,legal_basis='TRANSACTIONAL TEST ONLY',notice_version='test-only',notice_text='TRANSACTIONAL TEST NOTICE. This is rolled back and never published.',policy_url='https://example.invalid/privacy',retention_days=1,validated_at=now(),validated_by=a where id=1;
 select id,asking_price into vid,price from public.motta_vehicles where publication_status='published' and commercial_status='available' and archived_at is null limit 1;
 if vid is not null then p=p||jsonb_build_object('vehicle_id',vid);end if;
 p=p||jsonb_build_object('email','','income_range','','monthly_income',5000,'employment_bond','','employment_duration','','employment_type','public_servant','full_address','Rua de Teste, 123, Centro, CEP 00000-000');
 p=p||jsonb_build_object('address_version',2,'postal_code','94810000','street','Rua de Teste','address_number','123','address_complement','','neighborhood','Centro');
 result=public.motta_financing_receive(p,key,'test-only');protocol1=result->>'protocol';
 select id into rid from public.motta_financing_applications where protocol=protocol1;
 if rid is null then raise exception 'Submission did not persist';end if;
 protocol2=public.motta_financing_receive(p,key,'test-only')->>'protocol';if protocol1<>protocol2 then raise exception 'Idempotency failed';end if;
 begin perform public.motta_financing_receive(p,gen_random_uuid(),'test-only');raise exception 'MISSING_DUPLICATE_GUARD';exception when others then if sqlerrm='MISSING_DUPLICATE_GUARD' then raise;end if;end;
 begin perform public.motta_financing_receive(p||'{"notes":"different"}'::jsonb,key,'test-only');raise exception 'MISSING_CONFLICT';exception when others then if sqlerrm='MISSING_CONFLICT' then raise;end if;end;
 if exists(select 1 from motta_private.financing_details where application_id=rid and position('52998224725' in encode(encrypted_payload,'escape'))>0) then raise exception 'CPF stored without encryption';end if;
 if (select extensions.pgp_sym_decrypt(encrypted_payload,motta_private.financing_key())::jsonb->>'cpf' from motta_private.financing_details where application_id=rid)<>'52998224725' then raise exception 'Encrypted payload cannot be recovered';end if;
 if vid is not null then update public.motta_vehicles set asking_price=asking_price+100 where id=vid;if (select (vehicle_snapshot->>'price')::numeric from public.motta_financing_applications where id=rid)<>price then raise exception 'Historical price changed';end if;end if;
 raw=public.motta_financing_admin('detail',jsonb_build_object('id',rid));if raw->'applicant'->>'cpf' not like '***%' then raise exception 'Initial detail not masked';end if;
 raw=public.motta_financing_admin('reveal',jsonb_build_object('id',rid));if raw->'applicant'->>'cpf'<>'52998224725' then raise exception 'Authorized reveal failed';end if;
 if raw->'applicant'->>'full_address'<>'Rua de Teste, 123, Centro, CEP 00000-000' then raise exception 'Address roundtrip failed';end if;
 if raw->'applicant'->>'postal_code'<>'94810000' or raw->'applicant'->>'neighborhood'<>'Centro' then raise exception 'Structured address roundtrip failed';end if;
 result=public.motta_financing_admin('list',jsonb_build_object('search','Transacional Ficha','from',to_char(now() at time zone 'America/Sao_Paulo','YYYY-MM-DD'),'to',to_char(now() at time zone 'America/Sao_Paulo','YYYY-MM-DD')));
 if (result->>'total')::integer<>1 or result->'rows'->0->>'applicant_name'<>'Teste Transacional Ficha' or result->'rows'->0 ? 'cpf' then raise exception 'Name search/date range/privacy failed';end if;
 result=public.motta_financing_admin('list',jsonb_build_object('to','2000-01-01'));if (result->>'total')::integer<>0 then raise exception 'Date filter failed';end if;
 perform public.motta_financing_admin('update',jsonb_build_object('id',rid,'status','archived','notes','Arquivamento transacional'));
 if (select status from public.motta_financing_applications where id=rid)<>'archived' then raise exception 'Archive not persisted';end if;
 perform public.motta_financing_admin('update',jsonb_build_object('id',rid,'status','in_service','assigned_to',a,'notes','Teste de atribuição e status'));
 if not exists(select 1 from public.motta_financing_applications where id=rid and assigned_to=a and status='in_service') then raise exception 'Assignment/status failed';end if;
 begin perform public.motta_financing_admin('update',jsonb_build_object('id',rid,'status','approved','notes','Sem comprovação'));raise exception 'MISSING_EVIDENCE_GUARD';exception when others then if sqlerrm='MISSING_EVIDENCE_GUARD' then raise;end if;end;
 select id into institution from public.motta_financing_institutions where enabled limit 1;
 perform public.motta_financing_admin('disclose',jsonb_build_object('id',rid,'institution_id',institution,'notes','Registro transacional de compartilhamento, não enviado','disclosed_fields','["nome","veiculo"]'::jsonb));
 perform public.motta_financing_admin('update',jsonb_build_object('id',rid,'status','approved','assigned_to',a,'notes','Resposta fictícia apenas neste teste transacional','institution_confirmed',true,'evidence_reference','TEST-TRANSACTIONAL-ONLY'));
 perform public.motta_financing_admin('task_save',jsonb_build_object('id',rid,'title','Tarefa transacional','assigned_to',a));
 select id into taskid from motta_private.financing_tasks where application_id=rid limit 1;
 perform public.motta_financing_admin('task_complete',jsonb_build_object('id',rid,'task_id',taskid));if not exists(select 1 from motta_private.financing_tasks where id=taskid and completed_at is not null) then raise exception 'Task completion failed';end if;
 perform public.motta_financing_admin('link_customer',jsonb_build_object('id',rid));select customer_id into customer from public.motta_financing_applications where id=rid;
 perform public.motta_financing_admin('link_customer',jsonb_build_object('id',rid));if (select customer_id from public.motta_financing_applications where id=rid)<>customer then raise exception 'Customer duplicated';end if;
 if not exists(select 1 from motta_private.financing_events where application_id=rid and event_type='view_full') then raise exception 'Access audit missing';end if;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);
 perform public.motta_financing_admin('reveal',jsonb_build_object('id',rid));
 begin perform public.motta_financing_admin('export',jsonb_build_object('id',rid));raise exception 'MISSING_EXPORT_GUARD';exception when others then if sqlerrm='MISSING_EXPORT_GUARD' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',seller_id::text,true);
 execute 'set local role authenticated';
 select count(*) into n from public.motta_financing_applications;if n<>0 then raise exception 'RLS exposed summaries to seller';end if;
 begin perform public.motta_financing_admin('reveal',jsonb_build_object('id',rid));raise exception 'MISSING_SELLER_GUARD';exception when insufficient_privilege then null;end;
 begin perform count(*) from motta_private.financing_details;raise exception 'MISSING_PRIVATE_TABLE_GUARD';exception when insufficient_privilege then null;end;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',blocked_id::text,true);
 begin perform public.motta_financing_admin('detail',jsonb_build_object('id',rid));raise exception 'MISSING_BLOCKED_GUARD';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform public.motta_financing_admin('reveal',jsonb_build_object('id',rid));raise exception 'MISSING_PERMISSION_GUARD';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 delete from motta_private.financing_rate_limits r where r.key in ('global-hour',repeat('a',64));
 for n in 1..10 loop if not public.motta_financing_rate(repeat('a',64)) then raise exception 'Rate unexpectedly blocked';end if;end loop;
 if public.motta_financing_rate(repeat('a',64)) then raise exception 'Rate limiting failed';end if;
 update public.motta_financing_applications set expires_at=now()-interval '1 minute' where id=rid;perform motta_private.financing_purge();if exists(select 1 from motta_private.financing_details where application_id=rid) then raise exception 'Retention purge failed';end if;
end $$;
rollback;
